-- Build landing: the 16 catalogue motorcycles, in Garage 27's order.
-- Generated from src/data/catalogue/bikes.ts (local and Supabase stay identical).
-- Models without a 3D rig are active with no slots: the bay offers preview + quote.
-- A bike without an approved price has no base_price: the bay shows PRICE ON REQUEST.
alter table public.bikes add column if not exists tagline text;
alter table public.bikes alter column base_price drop not null;

update public.bikes set sort_order = 0, tagline = 'Timeless. Iconic. Yours.' where id = 'bike-re-classic-350';
update public.bikes set sort_order = 7 where id = 'bike-jawa-42';

